public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt();
        long k = r.nextLong();
        // Key sorts positions by (speed, index).
        long[] key = new long[n];
        for (int i = 0; i < n; i++) key[i] = (r.nextLong() << 18) | i;
        Arrays.sort(key);
        int mask = (1 << 18) - 1, ans = 0;
        for (int s = 0; s < n;) {
            int e = s;
            while (e < n && (key[e] >> 18) == (key[s] >> 18)) e++;
            int left = s;
            for (int right = s; right < e; right++) {
                while ((key[right] & mask) - (key[left] & mask) - (right - left) > k) left++;
                ans = Math.max(ans, right - left + 1);
            }
            s = e;
        }
        System.out.println(ans);
    }
}

final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

